const { withPodfile } = require('expo/config-plugins');

const MARKER = '# [withPodsDeploymentTarget]';

// Xcode 27 rejects pod deployment targets below 15.0 (e.g. SDWebImage at 9.0,
// RNCAsyncStorage at 13.4), which failed the Build 16 archive. `ios/` is
// regenerated by `expo prebuild` (locally and in Xcode Cloud), so the fix has
// to be injected into the generated Podfile rather than edited by hand.
const SNIPPET = `
    ${MARKER}
    installer.pods_project.targets.each do |pod_target|
      pod_target.build_configurations.each do |pod_config|
        current_target = pod_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET']
        if current_target && Gem::Version.new(current_target) < Gem::Version.new('15.0')
          pod_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '15.0'
        end
      end
    end
`;

module.exports = function withPodsDeploymentTarget(config) {
  return withPodfile(config, (config) => {
    const podfile = config.modResults;
    if (podfile.contents.includes(MARKER)) {
      return config;
    }
    const postInstall = /post_install do \|installer\|\n/;
    if (!postInstall.test(podfile.contents)) {
      throw new Error('withPodsDeploymentTarget: no post_install block found in Podfile');
    }
    podfile.contents = podfile.contents.replace(postInstall, (match) => match + SNIPPET);
    return config;
  });
};
